export interface RemediationPlanDocument {
  title: string;
  steps: string[];
  proposal?: string;
  priority?: { score: number; label: string };
  evidenceUrl?: string;
  evidenceLabel?: string;
  approved?: boolean;
  safetyChecks?: string[];
}

/** Format an advisory remediation checklist for offline review and sharing. */
export function formatRemediationPlanMarkdown(plan: RemediationPlanDocument, generatedAt = new Date()): string {
  const steps = plan.steps.map((step) => step.trim()).filter(Boolean);
  return [
    "# " + plan.title.trim(),
    "",
    "Generated by AgentIQ on " + generatedAt.toISOString() + ".",
    "",
    ...(plan.priority ? ["## Priority", "", plan.priority.score + "/100 · " + plan.priority.label, ""] : []),
    ...(plan.proposal ? ["## Proposed fix", "", plan.proposal, ""] : []),
    ...(plan.evidenceUrl ? ["## Source evidence", "", (plan.evidenceLabel || "Evidence") + ": " + plan.evidenceUrl, ""] : []),
    ...(plan.approved !== undefined ? ["## Human review", "", plan.approved ? "Approved for manual implementation in the current session." : "Not approved.", ""] : []),
    ...(plan.safetyChecks?.length ? ["## Safety checks", "", ...plan.safetyChecks.map((check) => "- " + check), ""] : []),
    "## Remediation checklist",
    "",
    ...(steps.length ? steps.map((step, index) => (index + 1) + ". " + step) : ["No steps were provided."]),
    "",
    "## Safety boundary",
    "",
    "This is an advisory plan, not an executed remediation. No repository files were changed, no code was executed, and no pull request was opened or merged by generating this document.",
    "",
    "Verify each finding against the source evidence and obtain human review before applying changes.",
    "",
  ].join("\n");
}
